input.command:
cd /workspace/work
cat > /tmp/stage1.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
COPY (SELECT 3 AS n_collections, 'trazo3-fields' AS recommended_id) TO '/workspace/answers/q01.csv' (HEADER, DELIMITER ',');
COPY (SELECT tier, count(*) AS n FROM read_parquet('/workspace/work/facilities.parquet') GROUP BY tier ORDER BY tier)
  TO '/workspace/answers/q02.csv' (HEADER, DELIMITER ',');
COPY (SELECT 8453554 AS n_rows, 8437940 AS n_distinct_ids) TO '/workspace/answers/q03.csv' (HEADER, DELIMITER ',');
COPY (SELECT 772404 AS n_rows, 4326 AS epsg) TO '/workspace/answers/q04.csv' (HEADER, DELIMITER ',');
EOF
duckdb /workspace/work/work.db < /tmp/stage1.sql 2>&1 | tail
echo "=== q02 ==="; cat /workspace/answers/q02.csv

cd /workspace/work
cat > /tmp/stage2.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
.mode duckbox
.print === q07 checks ===
SELECT count(*) FILTER(num_area<1) n_under_1ha FROM resolved;
.print === q06 preview ===
SELECT municipio, count(*) n FROM resolved GROUP BY municipio ORDER BY n DESC, municipio;
EOF
duckdb /workspace/work/work.db < /tmp/stage2.sql 2>&1 | tail -30

cd /workspace/work
cat > /tmp/stage2w.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
COPY (SELECT 117 AS list_ids, 117 AS found_in_car, 0 AS missing) TO '/workspace/answers/q05.csv' (HEADER,DELIMITER',');
COPY (SELECT municipio, count(*) AS n_parcels FROM resolved GROUP BY municipio ORDER BY n_parcels DESC, municipio) TO '/workspace/answers/q06.csv' (HEADER,DELIMITER',');
COPY (SELECT 0 AS n_duplicate_ids, 0 AS n_parcels_under_1ha) TO '/workspace/answers/q07.csv' (HEADER,DELIMITER',');
COPY (SELECT 119 AS input_rows, 114 AS resolved_clean, 1 AS centroid_resolved, 1 AS geometry_resolved, 1 AS axis_repaired, 1 AS duplicates_removed, 1 AS unresolvable) TO '/workspace/answers/q31.csv' (HEADER,DELIMITER',');
EOF
duckdb /workspace/work/work.db < /tmp/stage2w.sql 2>&1 | tail
echo "stage2 written"; ls /workspace/answers/

cd /workspace/work
cat > /tmp/env.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
.mode duckbox
SELECT min(ST_XMin(geom)) xmin, max(ST_XMax(geom)) xmax, min(ST_YMin(geom)) ymin, max(ST_YMax(geom)) ymax
FROM resolved;
EOF
duckdb /workspace/work/work.db < /tmp/env.sql 2>&1 | tail

cd /workspace/work
cat > /tmp/mproj.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE OR REPLACE TABLE fields_m AS
  SELECT field_id, mbmode24,
    deforestarea0104, deforestarea0509, deforestarea1014, deforestarea1520, deforestarea2124,
    ST_Transform(geom,'EPSG:4326','EPSG:5880') AS gm
  FROM fields;
ALTER TABLE fields_m ADD COLUMN farea DOUBLE;
UPDATE fields_m SET farea = ST_Area(gm);
CREATE OR REPLACE TABLE parcels_m AS
  SELECT cod_imovel, muni_code, municipio, num_area,
    ST_Transform(geom,'EPSG:4326','EPSG:5880') AS gm
  FROM resolved;
.mode duckbox
SELECT count(*) nf, min(farea) minfa, max(farea) maxfa FROM fields_m;
SELECT count(*) np FROM parcels_m;
EOF
duckdb /workspace/work/work.db < /tmp/mproj.sql 2>&1 | tail

cd /workspace/work
cat > /tmp/match.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
-- pairwise single-parcel intersection fractions (positive area only)
CREATE OR REPLACE TABLE pairs AS
  SELECT f.field_id, p.cod_imovel, p.muni_code,
    ST_Area(ST_Intersection(f.gm, p.gm)) AS inter_area,
    f.farea,
    ST_Area(ST_Intersection(f.gm, p.gm)) / f.farea AS single_frac
  FROM fields_m f JOIN parcels_m p ON ST_Intersects(f.gm, p.gm)
  WHERE ST_Area(ST_Intersection(f.gm, p.gm)) > 0;
-- buffered dissolved union (25 m) of all parcels
CREATE OR REPLACE TABLE bunion AS
  SELECT ST_Union_Agg(ST_Buffer(gm, 25.0)) AS gm FROM parcels_m;
-- union fraction per field (only for fields that touch any parcel)
CREATE OR REPLACE TABLE ufrac AS
  SELECT f.field_id,
    ST_Area(ST_Intersection(f.gm, b.gm)) / f.farea AS union_frac
  FROM fields_m f, bunion b
  WHERE ST_Intersects(f.gm, b.gm);
.mode duckbox
SELECT count(DISTINCT field_id) fields_touching, count(*) npairs FROM pairs;
SELECT count(*) uf_rows FROM ufrac;
EOF
echo start $(date +%T)
duckdb /workspace/work/work.db < /tmp/match.sql 2>&1 | tail
echo done $(date +%T)

cd /workspace/work
cat > /tmp/s3w.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
COPY (SELECT 3291 AS n_fields_in_envelope) TO '/workspace/answers/q08.csv' (HEADER,DELIMITER',');
COPY (SELECT 793 AS matched_fields) TO '/workspace/answers/q09.csv' (HEADER,DELIMITER',');
COPY (SELECT 766 AS by_single_parcel_rule, 27 AS by_aggregate_rule_only) TO '/workspace/answers/q10.csv' (HEADER,DELIMITER',');
COPY (SELECT min(max_single_frac) AS min_single_frac, avg(max_single_frac) AS avg_single_frac, avg(union_frac) AS avg_union_frac
      FROM fieldmatch WHERE matched) TO '/workspace/answers/q11.csv' (HEADER,DELIMITER',');
COPY (SELECT 79 AS n_excluded) TO '/workspace/answers/q12.csv' (HEADER,DELIMITER',');
COPY (SELECT primary_cod AS cod_imovel, count(*) AS n_fields FROM fieldmatch WHERE matched
      GROUP BY primary_cod ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10) TO '/workspace/answers/q13.csv' (HEADER,DELIMITER',');
COPY (SELECT sum(farea)/10000.0 AS matched_field_ha FROM fieldmatch WHERE matched) TO '/workspace/answers/q14.csv' (HEADER,DELIMITER',');
EOF
duckdb /workspace/work/work.db < /tmp/s3w.sql 2>&1 | tail
echo "=== q11 ==="; cat /workspace/answers/q11.csv
echo "=== q13 ==="; cat /workspace/answers/q13.csv
echo "=== q14 ==="; cat /workspace/answers/q14.csv

cd /workspace/work
cat > /tmp/flag.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
-- flagged parcels: >=1 matched in-scope field with post2020 loss
CREATE OR REPLACE TABLE flagged AS
  SELECT DISTINCT cod_imovel FROM fe WHERE in_scope AND has_post2020;
-- dominant class per flagged parcel over ALL matched fields on the parcel
CREATE OR REPLACE TABLE domclass AS
WITH agg AS (
  SELECT e.cod_imovel, e.mb, sum(e.field_ha) AS ha
  FROM fe e WHERE e.cod_imovel IN (SELECT cod_imovel FROM flagged)
  GROUP BY e.cod_imovel, e.mb
),
r AS (
  SELECT cod_imovel, mb, ha,
    row_number() OVER (PARTITION BY cod_imovel ORDER BY ha DESC, mb ASC) rn
  FROM agg
)
SELECT cod_imovel, mb AS dominant_mb FROM r WHERE rn=1;
.mode duckbox
SELECT count(*) n_flagged FROM flagged;
SELECT dominant_mb, count(*) n FROM domclass GROUP BY dominant_mb ORDER BY dominant_mb;
EOF
duckdb /workspace/work/work.db < /tmp/flag.sql 2>&1 | tail -20

cd /workspace/work
cat > /tmp/fac_build.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
-- q25: in-scope commodities on list -> tier + coverage
COPY (SELECT * FROM (VALUES
  ('cattle','slaughter_point','covered'),
  ('soya','intake_point','covered')) AS t(annex1_commodity,tier,coverage) ORDER BY annex1_commodity)
  TO '/workspace/answers/q25.csv' (HEADER,DELIMITER',');
-- point facilities (distance tiers) in 5880
CREATE OR REPLACE TABLE fac_pts AS
  SELECT entity_id, entity_kind, tier, weight, basis, geom_method,
    ST_Transform(geometry,'OGC:CRS84','EPSG:5880') AS gm
  FROM read_parquet('/workspace/work/facilities.parquet')
  WHERE tier IN ('intake_point','slaughter_point','mill_point');
-- membership polygons (matched by code)
CREATE OR REPLACE TABLE fac_mem AS
  SELECT entity_id, entity_kind, tier, weight, basis, geom_method
  FROM read_parquet('/workspace/work/facilities.parquet') WHERE tier='membership_muni';
-- gravity catchment polygons (4326)
CREATE OR REPLACE TABLE fac_catch AS
  SELECT entity_id, entity_kind, tier, weight, basis, geom_method, geometry AS gll
  FROM read_parquet('/workspace/work/facilities.parquet') WHERE tier='gravity_catchment';
.mode duckbox
SELECT tier, count(*) FROM fac_pts GROUP BY tier;
SELECT count(*) mem, count(DISTINCT entity_id) mem_ids FROM fac_mem;
SELECT count(*) catch FROM fac_catch;
EOF
duckdb /workspace/work/work.db < /tmp/fac_build.sql 2>&1 | tail -20

cd /workspace/work
cat > /tmp/mem_chk.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
.mode duckbox
.print === membership entity_id samples ===
SELECT entity_id, weight FROM fac_mem LIMIT 5;
.print === membership match for our muni codes ===
SELECT entity_id, weight FROM fac_mem WHERE entity_id IN ('5212204','5219258');
.print === distinct muni_codes of flagged ===
SELECT DISTINCT muni_code FROM fparcel;
EOF
duckdb /workspace/work/work.db < /tmp/mem_chk.sql 2>&1 | tail -30

cd /workspace/work
cat > /tmp/cand.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
-- delivery candidates within 300km of routed tier (capacity>=1000 for intake)
COPY (
  SELECT p.cod_imovel, f.entity_id, f.entity_kind, f.tier, f.weight, f.geom_method, f.basis,
         ST_Distance(p.cen_m, f.gm)/1000.0 AS distance_km
  FROM fparcel p JOIN fac_pts f ON f.tier = p.routed_tier
  WHERE ST_Distance(p.cen_m, f.gm)/1000.0 <= 300.0
    AND (f.tier <> 'intake_point' OR f.weight >= 1000)
) TO '/tmp/deliv_cand.csv' (HEADER,DELIMITER',');
-- membership candidates
COPY (
  SELECT p.cod_imovel, m.entity_id, m.entity_kind, m.tier, m.weight, m.geom_method, m.basis
  FROM fparcel p JOIN fac_mem m ON m.entity_id = p.muni_code
) TO '/tmp/mem_cand.csv' (HEADER,DELIMITER',');
-- gravity catchment candidates (only relevant where intake routed, but compute for all)
COPY (
  SELECT p.cod_imovel, c.entity_id, c.entity_kind, c.tier, c.weight, c.geom_method, c.basis
  FROM fparcel p JOIN fac_catch c ON ST_Contains(c.gll, p.cen_ll)
) TO '/tmp/catch_cand.csv' (HEADER,DELIMITER',');
-- parcel master export
COPY (SELECT cod_imovel, dominant_mb, annex1_commodity, routed_tier, muni_code, post2020_loss_ha
      FROM fparcel) TO '/tmp/parcels.csv' (HEADER,DELIMITER',');
EOF
echo start $(date +%T)
duckdb /workspace/work/work.db < /tmp/cand.sql 2>&1 | tail
echo done $(date +%T)
echo "deliv rows:"; wc -l /tmp/deliv_cand.csv
echo "mem rows:"; wc -l /tmp/mem_cand.csv
echo "catch rows:"; wc -l /tmp/catch_cand.csv
echo "=== catch preview ==="; cat /tmp/catch_cand.csv

cd /workspace/work
cat > /tmp/storedarea.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
-- pull canonical stored field area (ha) for matched fields
CREATE OR REPLACE TABLE farea_store AS
  SELECT t.Id AS field_id, t.mbvalid_area_2024/10000.0 AS stored_ha
  FROM read_parquet('/workspace/work/trazo3.parquet') t
  WHERE t.Id IN (SELECT field_id FROM fe);
ALTER TABLE fe ADD COLUMN IF NOT EXISTS stored_ha DOUBLE;
UPDATE fe SET stored_ha = (SELECT stored_ha FROM farea_store s WHERE s.field_id=fe.field_id);
.mode duckbox
